\label{thm:seriesexpansion}
Let $\G \subseteq \O(d)$ be any compact subgroup. Fix any $\theta_* \in \R^d$
and any integer $K \geq 0$.
\begin{enumerate}[(a)]
\item In the unprojected orbit recovery model, $R(\theta)$
admits an expansion
\begin{equation}\label{eq:seriesexpansionunprojected}
R(\theta)=C_0+\sum_{k=1}^K \frac{1}{\sigma^{2k}}\,
\Big(s_k(\theta)+q_k(\theta)\Big)+q(\theta).
\end{equation}
Here $C_0 \in \R$, $q_k \in \cR_{\leq k-1}^\G$ is a polynomial of degree
at most $2k$, and $s_k \in \cR_{\leq k}^\G$ is the polynomial
\begin{equation}\label{eq:sk}
s_k(\theta)=\frac{1}{2(k!)}\|T_k(\theta)-T_k(\theta_*)\|_\HS^2.
\end{equation}
The remainder $q(\theta)$ is $\G$-invariant and satisfies,
for all $\theta \in \R^d$ with $\|\theta\| \leq \sigma$,
\begin{equation}\label{eq:remainderbound}
|q(\theta)| \leq \frac{C_K(1 \vee \|\theta\|)^{2K+2}}{\sigma^{2K+2}},\;\;
\|\nabla q(\theta)\| \leq \frac{C_K(1 \vee\|\theta\|)^{2K+1}}
{\sigma^{2K+2}},\;\;
\|\nabla^2 q(\theta)\| \leq \frac{C_K(1 \vee\|\theta\|)^{2K}}
{\sigma^{2K+2}}.
\end{equation}
\item In the projected orbit recovery model, $R(\theta)$ admits an expansion
\begin{equation}\label{eq:seriesexpansionprojected}
R(\theta)=C_0+\sum_{k=1}^K \frac{1}{\sigma^{2k}}\,
\Big(\ts_k(\theta)+\big\langle \tT_k(\theta),P_k(\theta)\big\rangle
+q_k(\theta)\Big)+q(\theta).
\end{equation}
Here $C_0 \in \R$, $q_k \in \tcR_{\leq k-1}^\G$ is a polynomial of
degree at most $2k$, all entries of $P_k$ are polynomials of degree at most $k$
belonging to $\tcR_{\leq k-1}^\G$, $P_k$ satisfies $P_k(\theta_*)=0$,
and $\ts_k \in \tcR_{\leq k}^\G$ is the polynomial
\begin{equation}\label{eq:tildesk}
\ts_k(\theta)=\frac{1}{2(k!)}\|\tT_k(\theta)-\tT_k(\theta_*)\|_\HS^2.
\end{equation}
The remainder $q(\theta)$ is
$\G$-invariant and satisfies (\ref{eq:remainderbound}) for all 
$\theta \in \R^d$ with $\|\theta\| \leq \sigma$.
\end{enumerate}
The above constants $C_0,C_K$, the coefficients of the polynomials
$q_k(\theta)$ and $P_k(\theta)$, and the forms of the functions $q(\theta)$
may all depend on $\theta_*,\G,d,\td$, and the projection $\Pi$.

 \label{thm:cryoEM}
For any $L \geq 1$ and $S_0,\ldots,S_L \geq 2$, we have
\begin{align*}
\trdeg(\cR_{\leq 1}^\G)&=S_0\\
\trdeg(\cR_{\leq 2}^\G)&=\sum_{l=0}^L d(S_l),
\qquad d(S_l) \equiv
\begin{cases} \frac{S_l(S_l+1)}{2} & \text{ for } S_l<2l+1\\
(2l+1)(S_l-l) & \text{ for } S_l \geq 2l+1 \end{cases}\\
\trdeg(\cR_{\leq 3}^\G)&=\trdeg(\cR^\G)=d-3.
\end{align*}

\label{thm:cryoEM-mom}
For any $L \geq 1$ and $S_0,\ldots,S_L \geq 1$,
\begin{align*}
s_1(\theta)&=\frac{1}{2}\sum_{s=1}^{S_0} \Big(u^{(0s)}(\theta)-
u^{(0s)}(\theta_*)\Big)^2\\
s_2(\theta)&=\frac{1}{4}\sum_{l=0}^L \frac{1}{2l+1}
\sum_{s,s'=1}^{S_l} \Big(\langle u^{(ls)}(\theta),u^{(ls')}(\theta) \rangle
-\langle u^{(ls)}(\theta_*),u^{(ls')}(\theta_*) \rangle\Big)^2\\
s_3(\theta)&=\frac{1}{12}\mathop{\sum_{l,l',l''=0}^L}_{|l-l'| \leq l'' \leq
l+l'} \frac{1}{2l''+1}\sum_{s=1}^{S_l}\sum_{s'=1}^{S_{l'}}\sum_{s''=1}^{S_{l''}}
\Big(B_{(l,s),(l',s'),(l'',s'')}(\theta)-B_{(l,s),(l',s'),(l'',s'')}(\theta_*)\Big)^2.\label{eq:S3cryoEM}
\end{align*}
